(() => {
  const {escape:e,url,tours:readTours,calendar:readCalendar}=VisaCatalog;
  const $=selector=>document.querySelector(selector);
  const text=key=>VisaContent.get(config,key),escaped=key=>e(text(key));
  const editorPreview=new URLSearchParams(location.search).has('editor-preview')&&parent!==window;
  const modal=$('#tour-modal'),detail=$('#tour-detail'),form=$('#lead-form'),tourSelect=$('#tour-select'),dateSelect=$('#date-select');
  const nav=$('#site-nav'),toggle=$('#nav-toggle'),rail=$('#departures');
  let config={},catalog=[],departures=[],category='group',selectedDeparture='',returnFocus=null;
  const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';
  const descriptionKeys={group:'formatGroupDescription',expedition:'formatExpeditionDescription',private:'formatPrivateDescription'};
  const photo=(src,alt,extra='')=>url(src)?`<img src="${e(url(src))}" alt="${e(alt)}" ${extra}>`:'';
  const formatDate=value=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T12:00:00Z')).replace(/ г\.$/,'');
  function dateLabel(d){if(!d.start||!Number.isFinite(Date.parse(d.start)))return d.label||text('datesUnknown');const start=new Date(d.start+'T12:00:00Z'),end=d.end?new Date(d.end+'T12:00:00Z'):null;return end&&start.getUTCFullYear()===end.getUTCFullYear()&&start.getUTCMonth()===end.getUTCMonth()?`${start.getUTCDate()}–${formatDate(d.end)}`:formatDate(d.start)+(end?' — '+formatDate(d.end):'')}
  const whatsapp=()=>url(text('whatsappUrl'))||'https://wa.me/message/QHA2WWUW5XGED1';
  function closeMenu(){nav.classList.remove('is-open');toggle.setAttribute('aria-expanded','false')}
  toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)});
  nav.addEventListener('click',event=>{if(event.target.closest('a'))closeMenu()});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&toggle.getAttribute('aria-expanded')==='true'){closeMenu();toggle.focus()}});
  function renderFormats(){
    $('#format-description').textContent=text(descriptionKeys[category]);
    const list=catalog.filter(t=>t.category===category);
    $('#catalog').innerHTML=list.length?list.map(t=>`<article class="format-tour"><div class="format-tour-copy"><h3>${e(t.title)}</h3><p>${e(t.desc||t.route)}</p><button type="button" class="button button-accent" data-tour="${e(t.id)}" aria-haspopup="dialog" aria-label="Подробнее о путешествии ${e(t.title)}">${escaped('tourDetailsButton')}</button></div>${photo(t.image,t.title,'loading="lazy" decoding="async"')}</article>`).join(''):`<p class="empty-state">${escaped('formatsEmpty')} <a class="text-link" href="#contact">${escaped('pickTrip')}</a></p>`;
  }
  const tabs=[...document.querySelectorAll('[role="tab"]')];
  function selectTab(tab){category=tab.dataset.filter;tabs.forEach(item=>{const active=item===tab;item.setAttribute('aria-selected',String(active));item.tabIndex=active?0:-1});$('#format-panel').setAttribute('aria-labelledby',tab.id);renderFormats()}
  tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();selectTab(tabs[next])})});
  function availability(d,t){if(d.places)return (d.status||t.status||'')+' · '+d.places;if(/скоро|анонс/i.test(d.status||''))return d.status;if(Number.isInteger(d.remainingPlaces)&&d.remainingPlaces>=0)return text('availabilityPrefix')+' '+d.remainingPlaces;return d.status||t.status||text('askPlaces')}
  function renderCalendar(){
    rail.innerHTML=departures.length?departures.map(d=>{const t=catalog.find(t=>t.id===d.tourId);return `<button type="button" class="departure-card" data-tour="${e(t.id)}" data-departure="${e(d.id)}" aria-haspopup="dialog" aria-label="${e(t.title)}, ${e(dateLabel(d))}. Открыть программу">${photo(t.image,'','loading="lazy" decoding="async"')}<time class="departure-date" ${d.start?`datetime="${e(d.start)}"`:''}>${e(dateLabel(d))}</time><h3>${e(t.title)}</h3><p>${e(t.days)}</p><span class="departure-status">${e(availability(d,t))}</span></button>`}).join(''):`<p>${escaped('calendarEmpty')} <a class="text-link" href="#contact">${escaped('askTrip')}</a></p>`;
    requestAnimationFrame(syncRail);
  }
  function syncRail(){const buttons=document.querySelectorAll('[data-scroll]');buttons[0].disabled=rail.scrollLeft<=1;buttons[1].disabled=rail.scrollLeft+rail.clientWidth>=rail.scrollWidth-2}
  document.querySelectorAll('[data-scroll]').forEach(button=>button.addEventListener('click',()=>rail.scrollBy({left:Number(button.dataset.scroll)*((rail.querySelector('.departure-card')?.offsetWidth||300)+18),behavior:motion()})));
  rail.addEventListener('scroll',syncRail,{passive:true});window.addEventListener('resize',syncRail);
  function updateDates(preferred){const id=tourSelect.selectedOptions[0]?.dataset.tourId;const dates=departures.filter(d=>d.tourId===id);dateSelect.innerHTML=dates.length?dates.map(d=>`<option data-departure-id="${e(d.id)}" value="${e(dateLabel(d))}">${e(dateLabel(d))}</option>`).join(''):`<option value="${escaped('flexibleDates')}">${escaped('flexibleDates')}</option>`;if(preferred){const option=[...dateSelect.options].find(o=>o.dataset.departureId===preferred);if(option)dateSelect.value=option.value}}
  tourSelect.addEventListener('change',()=>updateDates());
  function applyContent(){VisaContent.apply(config);window.VisaHero?.mount(config);}
  function render(){const previous=tourSelect.value,previousDate=dateSelect.selectedOptions[0]?.dataset.departureId;catalog=readTours(config).filter(t=>t.published);departures=readCalendar(config,catalog).filter(d=>d.published!==false&&catalog.some(t=>t.id===d.tourId)).sort((a,b)=>(a.start||'9999').localeCompare(b.start||'9999'));renderFormats();renderCalendar();tourSelect.innerHTML=catalog.length?catalog.map(t=>`<option data-tour-id="${e(t.id)}" value="${e(t.title)}">${e(t.title)}</option>`).join(''):`<option value="${escaped('selectTripHelp')}">${escaped('selectTripHelp')}</option>`;if([...tourSelect.options].some(o=>o.value===previous))tourSelect.value=previous;updateDates(previousDate);applyContent();document.dispatchEvent(new Event('visa-content-ready'))}
  function openTour(id,departureId=''){
    const t=catalog.find(t=>t.id===id);if(!t)return false;
    selectedDeparture=departures.some(d=>d.id===departureId&&d.tourId===id)?departureId:'';
    const dates=departures.filter(d=>d.tourId===id),selected=dates.find(d=>d.id===selectedDeparture);
    const faqs=Array.isArray(config.faqs)&&config.content?.faqVersion==='2'?config.faqs:config.faqs?.length?config.faqs:VisaDefaults.faqs;
    const program=t.program.map((item,index)=>{const day=typeof item==='string'?{title:item}:item;return `<li><span>${escaped('dayLabel')} ${index+1}</span><div><h4>${e(day.title)}</h4>${day.description?`<p>${e(day.description)}</p>`:''}${day.image?photo(day.image,day.title,'loading="lazy"'):''}</div></li>`}).join('');
    detail.innerHTML=`<div class="detail-cover">${photo(t.image,'')}<h2 id="tour-modal-title">${e(t.title)}</h2><p>${e(t.route)}</p></div><div class="detail-body"><p>${e(t.desc)}</p><dl class="detail-facts"><div><dt>${escaped('tourDuration')}</dt><dd>${e(t.days)}</dd></div><div><dt>${escaped('tourPrice')}</dt><dd>${e(t.price)}</dd></div><div><dt>${escaped('tourDates')}</dt><dd>${e(selected?dateLabel(selected):dates.map(dateLabel).join(' / ')||t.dates)}</dd></div></dl><h3>${escaped('tourProgram')}</h3>${program?`<ol class="detail-days">${program}</ol>`:`<p>${escaped('programEmpty')}</p>`}${t.gallery.length?`<div class="detail-gallery">${t.gallery.map((item,i)=>photo(typeof item==='string'?item:item.url,item.alt||t.title+' — фото '+(i+1),'loading="lazy"')).join('')}</div>`:''}<div class="detail-inclusions"><div><h3>${escaped('tourIncluded')}</h3>${t.included.length?'<ul>'+t.included.map(v=>'<li>'+e(v)+'</li>').join('')+'</ul>':`<p>${escaped('includedEmpty')}</p>`}</div><div><h3>${escaped('tourExcluded')}</h3>${t.excluded.length?'<ul>'+t.excluded.map(v=>'<li>'+e(v)+'</li>').join('')+'</ul>':`<p>${escaped('excludedEmpty')}</p>`}</div></div>${faqs.length?`<div class="detail-questions"><h3>${escaped('tourQuestions')}</h3>${faqs.map(([q,a])=>`<details name="tour-questions"><summary>${e(q)}</summary><p>${e(a)}</p></details>`).join('')}</div>`:''}</div><div class="detail-booking"><p>${e(selected?availability(selected,t):t.status)}</p><button type="button" class="button button-accent" data-book-tour="${e(t.id)}">${escaped('tourBook')}</button></div>`;
    if(!modal.open){returnFocus=document.activeElement;modal.showModal();document.body.classList.add('modal-open')}
    modal.scrollTop=0;return true;
  }
  function setTourHash(id,departure){const params=new URLSearchParams({tour:id});if(departure)params.set('departure',departure);history.replaceState(null,'','#'+params.toString())}
  document.addEventListener('click',event=>{const trigger=event.target.closest('[data-tour]');if(trigger){if(openTour(trigger.dataset.tour,trigger.dataset.departure))setTourHash(trigger.dataset.tour,trigger.dataset.departure);return}const book=event.target.closest('[data-book-tour]');if(book){const option=[...tourSelect.options].find(o=>o.dataset.tourId===book.dataset.bookTour);if(option)tourSelect.value=option.value;updateDates(selectedDeparture);modal.close();history.replaceState(null,'','#contact');$('#contact').scrollIntoView({behavior:motion()});tourSelect.focus({preventScroll:true})}});
  $('.modal-close').addEventListener('click',()=>modal.close());
  modal.addEventListener('click',event=>{if(event.target!==modal)return;const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close()});
  modal.addEventListener('close',()=>{document.body.classList.remove('modal-open');if(location.hash.startsWith('#tour='))history.replaceState(null,'','#calendar');if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})});
  function handleHash(){const hash=location.hash.slice(1);if(hash.startsWith('tour=')){const params=new URLSearchParams(hash);if(!openTour(params.get('tour'),params.get('departure')))$('#page-status').textContent=text('missingTour');return}if(modal.open)modal.close();const aliases={'visa-support':'visas',faq:'contact'};const id=aliases[hash]||hash;const target=document.getElementById(id);if(!target)return;const details=target.closest('details');if(details)details.open=true;target.scrollIntoView({behavior:'instant'})}
  window.addEventListener('hashchange',handleHash);
  form.addEventListener('submit',async event=>{event.preventDefault();if(editorPreview){$('#form-status').textContent='Это предпросмотр. Заявки отсюда не отправляются.';return}const button=form.querySelector('[type="submit"]'),status=$('#form-status'),data=Object.fromEntries(new FormData(form));if(!data.name.trim()||!data.phone.trim()){status.textContent=text('leadRequired');return}button.disabled=true;status.className='form-status wide';status.textContent=text('leadSending');try{if(!window.visaSupabase)throw new Error('service unavailable');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const {error}=await window.visaSupabase.from('leads').insert({name:data.name.trim(),phone:data.phone.trim(),tour:data.tour,departure_date:data.date,comment:data.comment?.trim()||null}).abortSignal(controller.signal);if(error)throw error}finally{clearTimeout(timeout)}form.reset();updateDates();status.classList.add('is-success');status.textContent=text('leadSuccess')}catch(error){console.error('Lead submission failed',error);status.classList.add('is-error');status.innerHTML=`${escaped('leadError')} <a href="${whatsapp()}" target="_blank" rel="noopener">${escaped('leadWhatsapp')}</a>.`}finally{button.disabled=false}});
  // Saved tours render immediately; the editor's published content replaces them when available.
  window.VisaLanding={preview:draft=>{config=draft;render();if(location.hash.startsWith('#tour='))handleHash()}};
  render();requestAnimationFrame(handleHash);
  (async()=>{if(editorPreview||!window.visaSupabase)return;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),6000);try{const {data,error}=await window.visaSupabase.from('site_config').select('*').eq('id','main').maybeSingle().abortSignal(controller.signal);if(error)throw error;if(data){config={content:data.content||{},media:data.media||{},tours:data.tours||[],faqs:data.faqs||[],updatedAt:data.updated_at};render();if(location.hash.startsWith('#tour='))handleHash();window.VisaLive?.watch(config.updatedAt)}}catch{$('#page-status').textContent=text('offlineCatalog')}finally{clearTimeout(timeout)}})();
})();
